sys_script.script:
(function executeRule(current, previous /*null when async*/) {

        var gr = new GlideRecord(current.getTableName());
       // gr.addEncodedQuery('state=1^ORstate=2' + current.assigned_to);
        gr.addQuery('assigned_to',current.assigned_to);
		gr.addEncodedQuery('state=1^ORstate=2');
		gr.addQuery('sys_id', '!=', current.sys_id);
		gr.query();

        if (gr.next()) {
            gs.addErrorMessage('incident tickect is opened or working in progress please work on it')
            current.setAbortAction(true);
        }

})(current, previous);
